import { useState } from 'react';
import API from '../api/axios';

export default function CreatePost({ onPostCreated }) {
  const [text, setText] = useState('');
  const [image, setImage] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async e => {
    e.preventDefault();
    if (!text && !image) return;
    setLoading(true);
    try {
      const formData = new FormData();
      if (text) formData.append('text', text);
      if (image) formData.append('image', image);
      await API.post('/posts', formData);
      setText('');
      setImage(null);
      onPostCreated();
    } catch (err) {
      alert(err.response?.data?.message || 'Error creating post');
    }
    setLoading(false);
  };

  return (
    <div style={styles.card}>
      <h3 style={styles.title}>Create Post</h3>
      <form onSubmit={handleSubmit}>
        <textarea style={styles.textarea}
          placeholder="What's on your mind?"
          value={text}
          onChange={e => setText(e.target.value)}
          rows={3}
        />
        <div style={styles.row}>
          <input type="file" accept="image/*"
            onChange={e => setImage(e.target.files[0])}
            style={{ fontSize: '13px' }}
          />
          <button style={styles.button} type="submit" disabled={loading}>
            {loading ? 'Posting...' : 'Post'}
          </button>
        </div>
      </form>
    </div>
  );
}

const styles = {
  card: { background: '#fff', padding: '1.5rem', borderRadius: '12px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.08)', marginBottom: '1.5rem' },
  title: { margin: '0 0 1rem', color: '#1a1a2e' },
  textarea: { width: '100%', padding: '12px', borderRadius: '8px',
    border: '1px solid #ddd', fontSize: '15px',
    boxSizing: 'border-box', resize: 'vertical' },
  row: { display: 'flex', justifyContent: 'space-between',
    alignItems: 'center', marginTop: '1rem' },
  button: { padding: '10px 24px', background: '#4f46e5',
    color: '#fff', border: 'none', borderRadius: '8px',
    fontSize: '15px', cursor: 'pointer' },
};
